type CustomerDAO interface {                        // declared where consumed
	Find(ctx context.Context, id int64) (*Customer, error)
}

type sqlCustomerDAO struct{ db *sql.DB }            // only place SQL appears
func (d *sqlCustomerDAO) Find(ctx context.Context, id int64) (*Customer, error) {
	var c Customer
	err := d.db.QueryRowContext(ctx,
		`SELECT id, name, version FROM customer WHERE id = $1`, id).
		Scan(&c.ID, &c.Name, &c.Version)
	if errors.Is(err, sql.ErrNoRows) { return nil, ErrNotFound }
	return &c, err
}

