type DAO[T any] struct {
	db    *sql.DB
	table string                               // must come from a fixed allow-list
	scan  func(*sql.Rows) (T, error)           // per-entity hook
}
func (d DAO[T]) All(ctx context.Context) ([]T, error) {
	rows, err := d.db.QueryContext(ctx, "SELECT * FROM "+d.table)
	if err != nil { return nil, err }
	defer rows.Close()
	var out []T
	for rows.Next() { v, err := d.scan(rows); if err != nil { return nil, err }; out = append(out, v) }
	return out, rows.Err()
}
